{
  "root_cause": "The modal's focus trap (_enforceFocus) only handles forward focus escape via focusin event, but lacks a keydown handler for Shift+Tab backward wrapping. When Shift+Tab is pressed on the first focusable element (#confirm-close), focus should wrap to the last focusable element (#confirm-delete), but no logic intercepts this.",
  "repair_strategy": "Add a keydown event listener on the modal element for Tab key that wraps focus bidirectionally: Shift+Tab on first focusable element focuses last, Tab on last focuses first. Register in _enforceFocus (called on show transition complete) and deregister in hide.",
  "edits": [
    {
      "path": "js/src/modal.js",
      "sha256": "af810eae7fa73e5cb3f1e21175173eb0cee6a70c544a5fe8c70af93c9721a283",
      "before": "const EVENT_KEYDOWN_DISMISS = `keydown.dismiss${EVENT_KEY}`
const EVENT_MOUSEUP_DISMISS = `mouseup.dismiss${EVENT_KEY}`",
      "after": "const EVENT_KEYDOWN_DISMISS = `keydown.dismiss${EVENT_KEY}`
const EVENT_KEYDOWN_TAB = `keydown.tab${EVENT_KEY}`
const EVENT_MOUSEUP_DISMISS = `mouseup.dismiss${EVENT_KEY}`"
    },
    {
      "path": "js/src/modal.js",
      "sha256": "af810eae7fa73e5cb3f1e21175173eb0cee6a70c544a5fe8c70af93c9721a283",
      "before": "  _enforceFocus() {
    EventHandler.off(document, EVENT_FOCUSIN) // guard against infinite focus loop
    EventHandler.on(document, EVENT_FOCUSIN, event => {
      if (document !== event.target &&
          this._element !== event.target &&
          !this._element.contains(event.target)) {
        this._element.focus()
      }
    })
  }",
      "after": "  _enforceFocus() {
    EventHandler.off(document, EVENT_FOCUSIN) // guard against infinite focus loop
    EventHandler.on(document, EVENT_FOCUSIN, event => {
      if (document !== event.target &&
          this._element !== event.target &&
          !this._element.contains(event.target)) {
        this._element.focus()
      }
    })

    EventHandler.on(this._element, EVENT_KEYDOWN_TAB, event => {
      if (event.key !== 'Tab') return

      const focusable = this._dialog.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      )
      const focusableArray = Array.from(focusable).filter(el =>
        el.offsetParent !== null && !el.disabled && !el.hidden
      )

      if (focusableArray.length === 0) return

      const first = focusableArray[0]
      const last = focusableArray[focusableArray.length - 1]
      const active = document.activeElement

      if (event.shiftKey) {
        if (active === first) {
          event.preventDefault()
          last.focus()
        }
      } else {
        if (active === last) {
          event.preventDefault()
          first.focus()
        }
      }
    })
  }"
    },
    {
      "path": "js/src/modal.js",
      "sha256": "af810eae7fa73e5cb3f1e21175173eb0cee6a70c544a5fe8c70af93c9721a283",
      "before": "    EventHandler.off(document, EVENT_FOCUSIN)

    this._element.classList.remove(CLASS_NAME_SHOW)",
      "after": "    EventHandler.off(document, EVENT_FOCUSIN)
    EventHandler.off(this._element, EVENT_KEYDOWN_TAB)

    this._element.classList.remove(CLASS_NAME_SHOW)"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can navigate the delete confirmation modal bidirectionally with Tab/Shift+Tab, meeting WCAG 2.1.1 (Keyboard) and 2.4.3 (Focus Order).",
  "functional_risks": [
    "Minimal - only adds focus wrapping logic; no changes to existing focusin trap, backdrop, or dismissal behavior."
  ],
  "verification_requirements": [
    "Run the frozen journey "Move backwards through the delete confirmation" - Shift+Tab from Close button should focus Delete button.",
    "Verify Tab from Delete button wraps to Close button."
  ]
}
